def main():
    import sys

    def read_ints():
        return map(int, sys.stdin.readline().split())

    x1, y1, x2, y2 = read_ints()
    x3, y3, x4, y4 = read_ints()
    x5, y5, x6, y6 = read_ints()

    # Calculate the bounding box of the union of the two black sheets
    union_x1 = min(x3, x5)
    union_y1 = min(y3, y5)
    union_x2 = max(x4, x6)
    union_y2 = max(y4, y6)

    # Check if the union of the black sheets covers the white sheet
    if union_x1 <= x1 and union_y1 <= y1 and union_x2 >= x2 and union_y2 >= y2:
        print("NO")
    else:
        print("YES")

